import crypto from "node:crypto";
import fs from "node:fs";
import path from "node:path";
import process from "node:process";

const root = path.resolve(process.argv[2] ?? ".");
const required = ["main.js", "manifest.json", "styles.css"];
const assert = (condition, message) => {
  if (!condition) throw new Error(message);
};

for (const file of required) {
  const filePath = path.join(root, file);
  assert(fs.statSync(filePath).isFile(), `Missing release asset: ${file}`);
}

const main = fs.readFileSync(path.join(root, "main.js"), "utf8");
assert(
  main.startsWith("/*\nTHIS IS A GENERATED/BUNDLED FILE BY ESBUILD"),
  "main.js does not have the production bundle banner",
);
assert(!main.includes("sourceMappingURL="), "main.js contains a source map");
assert(
  !main.includes("sourcesContent"),
  "main.js contains development sources",
);
assert(main.length > 1_000, "main.js is unexpectedly small");

const forbidden = fs
  .readdirSync(root)
  .filter(
    (name) =>
      name.endsWith(".map") || (process.argv[2] && name === "data.json"),
  );
assert(
  forbidden.length === 0,
  `Forbidden release artifacts: ${forbidden.join(", ")}`,
);

const metadata = Object.fromEntries(
  required.map((file) => {
    const contents = fs.readFileSync(path.join(root, file));
    return [
      file,
      {
        bytes: contents.length,
        sha256: crypto.createHash("sha256").update(contents).digest("hex"),
      },
    ];
  }),
);
const artifactDir = path.join(process.cwd(), "artifacts");
fs.mkdirSync(artifactDir, { recursive: true });
fs.writeFileSync(
  path.join(artifactDir, "bundle-metadata.json"),
  `${JSON.stringify(metadata, null, 2)}\n`,
);
console.log("Production bundle valid.");
